# Generated by build.py from recipe.yml for recipe http-sign-requests-with-aws-sigv4. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site2' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site2/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--user', 'AKIAEXAMPLE:topsecret', '--auth', 'aws-sigv4', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --aws-sigv4 "aws:amz:us-east-1:s3" -u AKIAEXAMPLE:topsecret http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
